/**
 * Supabase database types (auto-generated from schema, or manually defined).
 * This is a placeholder for type safety; the actual types would be generated
 * via supabase gen types typescript or written by hand.
 */

export interface Database {
  public: {
    Tables: Record<string, unknown>;
    Views: Record<string, unknown>;
    Functions: Record<string, unknown>;
    Enums: Record<string, unknown>;
    CompositeTypes: Record<string, unknown>;
  };
}
